130	     * A single Luhn check digit (0-9) computed over the digits contained in the
131	     * {@link #customerCode}. Non-digit characters in the code are ignored; the standard Luhn
132	     * algorithm doubles every second digit from the right (subtracting 9 when the result exceeds
133	     * 9) and the check digit is {@code (10 - (sum % 10)) % 10}. {@code null} until a customer code
134	     * is assigned.
135	     */
136	    @Transient
137	    public Integer getCheckDigit() {
138	        if (this.customerCode == null) {
139	            return null;
140	        }
141	        int sum = 0;
142	        boolean dbl = true;
143	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
144	            char c = this.customerCode.charAt(i);
145	            if (c < '0' || c > '9') {
146	                continue;
147	            }
148	            int d = c - '0';
149	            if (dbl) {
150	                d *= 2;
151	                if (d > 9) {
152	                    d -= 9;
153	                }
154	            }
155	            sum += d;
156	            dbl = !dbl;
157	        }
158	        return (10 - (sum % 10)) % 10;
159	    }
