233	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
234	    private static String regionForPostcode(String postcode) {
235	        if (postcode == null) {
236	            return null;
237	        }
238	        int value;
239	        try {
240	            value = Integer.parseInt(postcode.trim());
241	        }
242	        catch (NumberFormatException ex) {
243	            return null;
244	        }
245	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
