279	
280	    private static boolean isBlank(String value) {
281	        return value == null || value.isBlank();
282	    }
283	
284	    /**
285	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
286	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
287	     */
288	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
289	        "NSW", new int[] {2000, 2099},
290	        "VIC", new int[] {3000, 3099},
291	        "QLD", new int[] {4000, 4099});
292	
293	    /**
294	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
295	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
296	     * present, the value has already passed the 4-digit format check (Bean Validation on the
297	     * request body); this enforces that it falls within the inclusive range for the city's region
298	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
299	     *
300	     * @param postcode the supplied postcode (may be {@code null})
301	     * @param region the owner's locality/region derived from its city
302	     * @throws InvalidPostcodeException if the postcode is out of range for the region
303	     */
304	    private static void validatePostcode(String postcode, String region) {
305	        if (isBlank(postcode)) {
306	            return;
307	        }
308	        int[] range = REGION_POSTCODES.get(region);
309	        if (range == null) {
310	            return;
311	        }
312	        int value;
313	        try {
314	            value = Integer.parseInt(postcode);
315	        }
316	        catch (NumberFormatException e) {
317	            throw new InvalidPostcodeException(postcode);
318	        }
319	        if (value < range[0] || value > range[1]) {
320	            throw new InvalidPostcodeException(postcode);
321	        }
322	    }
323	
324	    /**
325	     * Normalizes a street address into the canonical form stored on and returned for a newly
326	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
327	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
328	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
329	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
330	     * value is what gets persisted, echoed back, and used for every address comparison (household
331	     * duplicate detection and the shared household identifier).
332	     *
333	     * @param rawAddress the address value as supplied by the client
334	     * @return the normalized address (possibly empty, never {@code null})
335	     */
336	    private static String normalizeAddress(String rawAddress) {
337	        if (rawAddress == null) {
338	            return "";
339	        }
340	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
341	        if (collapsed.isEmpty()) {
342	            return "";
343	        }
344	        String[] tokens = collapsed.split(" ");
345	        StringBuilder sb = new StringBuilder(collapsed.length());
346	        for (int i = 0; i < tokens.length; i++) {
347	            String token = tokens[i];
348	            switch (token) {
349	                case "ST" -> token = "STREET";
350	                case "RD" -> token = "ROAD";
351	                case "AVE" -> token = "AVENUE";
352	                default -> { }
353	            }
354	            if (i > 0) {
355	                sb.append(' ');
356	            }
357	            sb.append(token);
358	        }
359	        return sb.toString();
360	    }
361	
362	    /**
363	     * Builds the customer code assigned to a newly created owner. The code is formatted
364	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
365	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
366	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
367	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
368	     * the owner's own region and identity.
369	     *
370	     * @param owner the owner being created, with telephone already normalized and postcode/city set
371	     * @return the customer code to assign
372	     */
373	    private static String customerCodeFor(Owner owner) {
374	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
375	    }
376	
377	    /**
378	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
379	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
380	     * last name.
381	     *
382	     * @param normalizedTelephone the owner's telephone in E.164 form
383	     * @param lastName the owner's last name
384	     * @return the 8-character upper-case hex hash
385	     */
386	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
387	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
388	            + (lastName == null ? "" : lastName);
389	        try {
390	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
391	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
392	            StringBuilder sb = new StringBuilder(digest.length * 2);
393	            for (byte b : digest) {
394	                sb.append(String.format("%02x", b));
395	            }
396	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
397	        }
398	        catch (java.security.NoSuchAlgorithmException e) {
399	            throw new IllegalStateException("SHA-256 not available", e);
400	        }
401	    }
402	
403	    /**
404	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
405	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
406	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
407	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
408	     * the national number must match the country code: {@code +61} requires 9 national digits and
409	     * {@code +1} requires 10.
410	     *
411	     * @param rawTelephone the telephone value as supplied by the client
412	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
413	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
414	     */
415	    private static String normalizeTelephone(String rawTelephone) {
416	        if (rawTelephone == null) {
417	            throw new InvalidTelephoneException(rawTelephone);
418	        }
419	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
420	        String e164;
421	        if (cleaned.startsWith("+")) {
422	            String digits = cleaned.substring(1);
423	            if (!digits.matches("[0-9]+")) {
424	                throw new InvalidTelephoneException(rawTelephone);
425	            }
426	            e164 = "+" + digits;
427	        } else {
428	            if (!cleaned.matches("[0-9]+")) {
429	                throw new InvalidTelephoneException(rawTelephone);
430	            }
431	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
432	            e164 = "+61" + national;
433	        }
434	        int digitCount = e164.length() - 1;
435	        if (digitCount < 8 || digitCount > 15) {
436	            throw new InvalidTelephoneException(rawTelephone);
437	        }
438	        if (e164.startsWith("+61")) {
439	            if (e164.length() - "+61".length() != 9) {
440	                throw new InvalidTelephoneException(rawTelephone);
441	            }
442	        }
443	        else if (e164.startsWith("+1")) {
444	            if (e164.length() - "+1".length() != 10) {
445	                throw new InvalidTelephoneException(rawTelephone);
446	            }
447	        }
448	        return e164;
449	    }
450	
451	    /**
452	     * Determines whether any existing owner already carries the given identity key. The identity key
453	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
454	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
455	     * are equal.
456	     *
457	     * @param identityKey the identity key of the owner being created
458	     * @return {@code true} if another owner already has the same identity key
459	     */
460	    private boolean isIdentityKeyInUse(String identityKey) {
461	        return this.clinicService.findAllOwners().stream()
462	            .map(Owner::getIdentityKey)
463	            .anyMatch(identityKey::equals);
464	    }
465	
466	    /**
467	     * Counts how many existing owners already share the given first name and last name with the
468	     * owner being created. Both names are compared case-insensitively (after trimming and
469	     * collapsing runs of whitespace). The count reflects the state before the new owner is
470	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
471	     *
472	     * @param firstName the first name of the owner being created
473	     * @param lastName the last name of the owner being created
474	     * @return the number of existing owners sharing the same first and last name
475	     */
476	    private int namesakeCount(String firstName, String lastName) {
477	        String normalizedFirstName = normalizeIdentity(firstName);
478	        String normalizedLastName = normalizeIdentity(lastName);
479	        return (int) this.clinicService.findAllOwners().stream()
480	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
481	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
482	            .count();
483	    }
484	
485	    /**
486	     * Counts how many members the owner being created belongs to in its household, including
487	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
488	     * the new owner is not yet persisted, so its own membership is added to the existing count.
489	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
490	     * household of one.
491	     *
492	     * @param householdId the shared household identifier assigned to the owner being created, or
493	     *                    {@code null} if the owner does not share a household
494	     * @return the number of household members after this create (at least 1)
495	     */
496	    private int householdSizeAfterCreate(String householdId) {
497	        if (householdId == null) {
498	            return 1;
499	        }
500	        long existing = this.clinicService.findAllOwners().stream()
501	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
502	            .count();
503	        return (int) existing + 1;
504	    }
505	
506	    /**
507	     * The maximum number of owners permitted in a single city. Once a city already contains this
508	     * many owners it is considered full and no further owners may be created there.
509	     */
510	    private static final int CITY_CAPACITY = 50;
511	
512	    /**
513	     * Determines whether the given city has already reached its capacity, i.e. already contains
514	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
515	     * collapsing runs of whitespace to a single space and trimming.
516	     *
517	     * @param city the city of the owner being created
518	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
519	     */
520	    private boolean isCityAtCapacity(String city) {
521	        String normalizedCity = normalizeIdentity(city);
522	        long count = this.clinicService.findAllOwners().stream()
523	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
524	            .count();
525	        return count >= CITY_CAPACITY;
526	    }
527	
528	    /**
529	     * The maximum number of owners that may be created on any single day. Once this many owners
530	     * already carry a {@code registrationDate} of the current day, no further owners may be created
531	     * that day.
532	     */
533	    private static final int DAILY_REGISTRATION_LIMIT = 100;
534	
535	    /**
536	     * Determines whether the daily registration limit has already been reached, i.e. whether
537	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
538	     * their {@code registrationDate}.
539	     *
540	     * @param date the current day
541	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
542	     *         registered on the given date
543	     */
544	    /**
545	     * Rolls a registration date forward onto a business day. A date that already falls on a
546	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
547	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
548	     * everything derived from it (the membership number's year segment, the daily create-limit).
549	     *
550	     * @param date the effective registration date (supplied by the client or defaulted to the
551	     *             server's current date)
552	     * @return the same date if it is a weekday, otherwise the following Monday
553	     */
554	    private static LocalDate toBusinessDay(LocalDate date) {
555	        DayOfWeek dayOfWeek = date.getDayOfWeek();
556	        if (dayOfWeek == DayOfWeek.SATURDAY) {
557	            return date.plusDays(2);
558	        }
559	        if (dayOfWeek == DayOfWeek.SUNDAY) {
560	            return date.plusDays(1);
561	        }
562	        return date;
563	    }
564	
565	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
566	        long count = this.clinicService.findAllOwners().stream()
567	            .filter(existing -> date.equals(existing.getRegistrationDate()))
568	            .count();
569	        return count >= DAILY_REGISTRATION_LIMIT;
570	    }
571	
572	    /**
573	     * The number of owners that may be created on a single day before the bulk-signup warning is
574	     * raised. Once <em>more than</em> this many owners already carry the current business day as
575	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
576	     */
577	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
578	
579	    /**
580	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
581	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
582	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
583	     *
584	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
585	     *         registered on today's business day
586	     */
587	    private boolean isBulkSignupWarning() {
588	        LocalDate today = toBusinessDay(LocalDate.now());
589	        long count = this.clinicService.findAllOwners().stream()
590	            .filter(existing -> today.equals(existing.getRegistrationDate()))
591	            .count();
592	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
593	    }
594	
595	    /**
596	     * Back-fills the given household identifier onto every existing member of the household (those
597	     * sharing the same last name and address) that does not yet carry it, so all household members
598	     * share the stable identifier regardless of creation order. The identifier itself is derived
599	     * deterministically by {@link #householdIdFor(String, String)}.
600	     *
601	     * @param lastName the last name of the owner being created
602	     * @param address the address of the owner being created
603	     * @param householdId the stable household identifier assigned to the owner being created
604	     */
605	    private void backfillHousehold(String lastName, String address, String householdId) {
606	        String normalizedLastName = normalizeIdentity(lastName);
607	        String normalizedAddress = normalizeIdentity(address);
608	        for (Owner existing : this.clinicService.findAllOwners()) {
609	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
610	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
611	                && !householdId.equals(existing.getHouseholdId())) {
612	                existing.setHouseholdId(householdId);
613	                this.clinicService.saveOwner(existing);
614	            }
615	        }
616	    }
617	
618	    /**
619	     * Derives the stable household identifier for a given last name and address. The value is the
620	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
621	     * address, so it is stable across calls and identical for every member of the household.
622	     *
623	     * @param lastName the last name of the household
624	     * @param address the address of the household
625	     * @return the stable household identifier
626	     */
627	    private static String householdIdFor(String lastName, String address) {
628	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
629	        try {
630	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
631	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
632	            StringBuilder sb = new StringBuilder(digest.length * 2);
633	            for (byte b : digest) {
634	                sb.append(String.format("%02x", b));
635	            }
636	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
637	        }
638	        catch (java.security.NoSuchAlgorithmException e) {
639	            throw new IllegalStateException("SHA-256 not available", e);
640	        }
641	    }
642	
643	    /**
644	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
645	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
646	     * single space, and the result is lower-cased.
647	     *
648	     * @param value the raw field value
649	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
650	     */
651	    private static String normalizeIdentity(String value) {
652	        if (value == null) {
653	            return "";
654	        }
655	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
656	    }
657	}
